svg.script:
{
  "diagramType": "Logical Data Model",
  "projectName": "Food Delivery System",
  "description": "Database tables with columns and relationships",
  "tables": [
    {
      "id": "users",
      "name": "users",
      "position": {"x": 240, "y": 300},
      "columns": [
        {"name": "user_id", "type": "INT", "pk": true},
        {"name": "name", "type": "VARCHAR(255)"},
        {"name": "email", "type": "VARCHAR(255)", "unique": true},
        {"name": "phone", "type": "VARCHAR(20)"},
        {"name": "address", "type": "TEXT"}
      ]
    },
    {
      "id": "restaurants",
      "name": "restaurants",
      "position": {"x": 800, "y": 300},
      "columns": [
        {"name": "restaurant_id", "type": "INT", "pk": true},
        {"name": "name", "type": "VARCHAR(255)"},
        {"name": "location", "type": "VARCHAR(255)"},
        {"name": "rating", "type": "DECIMAL(2,1)"},
        {"name": "cuisine", "type": "VARCHAR(100)"}
      ]
    },
    {
      "id": "orders",
      "name": "orders",
      "position": {"x": 1360, "y": 300},
      "columns": [
        {"name": "order_id", "type": "INT", "pk": true},
        {"name": "user_id", "type": "INT", "fk": "users"},
        {"name": "restaurant_id", "type": "INT", "fk": "restaurants"},
        {"name": "status", "type": "VARCHAR(50)"},
        {"name": "total", "type": "DECIMAL(10,2)"}
      ]
    }
  ],
  "relationships": [
    {"from": "users", "to": "orders", "type": "one_to_many"},
    {"from": "restaurants", "to": "orders", "type": "one_to_many"}
  ],
  "designTokens": {"lightMode": {"canvas": "#FFFFFF"}, "darkMode": {"canvas": "#0D0D0D"}}
}
